const input=$('Receber tarefa confirmada').item.json.body;
const people=$('Ler vínculos TMX').first().json.people;
const previous=$input.first().json.task;
if(!input || !input.eventId || !['discord','clickup'].includes(input.source)) throw new Error('Envelope inválido');
const remote=input.task;
if(!remote?.id || !/^[a-zA-Z0-9_-]+$/.test(String(remote.id))) throw new Error('taskId ausente');
const config=JSON.parse($vars.TMX_TASK_CONFIG_JSON || '{}');
const match=Object.entries(config).find(([sector,value])=>String(value.listId)===String(remote.list?.id));
if(!match) throw new Error('Lista ClickUp sem mapeamento de setor');
const [sector,settings]=match;
const state=Object.entries(settings.statuses).find(([key,value])=>value===remote.status?.status)?.[0];
if(!['pending','progress','done'].includes(state)) throw new Error('Status da lista não mapeado');
const iso=value=>value && Number.isFinite(Number(value))?new Date(Number(value)).toISOString():null;
const updatedAt=iso(remote.date_updated);
if(!updatedAt) throw new Error('Data de atualização ausente');
const assignees=(remote.assignees||[]).map(p=>{ const person=people.find(saved=>saved.clickupId===String(p.id)); if(!person) throw new Error('Responsável sem vínculo TMX: '+p.id); return person; });
const task={clickupId:String(remote.id),discordMessageId:input.discordMessageId||previous?.discordMessageId||null,discordChannelId:input.discordChannelId||previous?.discordChannelId||null,
title:String(remote.name||''),description:String(remote.description||''),sector,offer:input.offer||previous?.offer||String(remote.description||'').match(/Oferta:\s*([^\n]+)/i)?.[1]?.trim()||null,assignees,status:state,
priority:({1:'urgent',2:'high',3:'normal',4:'low'})[remote.priority?.id]||'normal',source:input.source,
receivedAt:iso(remote.date_created)||updatedAt,assignedAt:null,startedAt:input.startedAt||previous?.startedAt||null,
completedAt:state==='done'?iso(remote.date_done||remote.date_closed):null,dueAt:iso(remote.due_date),updatedAt,
syncState:'synced',discordState:'pending'};
if(previous) task.id=previous.id;
if(!/^\d+$/.test(String(input.discordMessageId||'')) || !/^\d+$/.test(String(input.discordChannelId||''))) throw new Error('Recibo Discord confirmado obrigatório');
task.discordState='synced';
return [{json:{eventId:String(input.eventId)+':confirmed',task}}];
